"""Копирование (не перенос) журналов команд ролей по проектам в Downloads/vibing."""
import glob
import os
import shutil

DEST = r"C:\Users\Георгий\Downloads\vibing"
CONV = r"C:\Users\Георгий\.claude\projects"
PROJECTS = [
    ("alpha", r"C:\visual projects\alpha", "C--visual-projects-alpha"),
    ("game", r"C:\visual projects\game", "C--visual-projects-game"),
    ("role-play-vibing", r"C:\visual projects\role-play-vibing", "C--visual-projects-role-play-vibing"),
    ("verger-vdev", r"C:\vdev\verger", "C--vdev-verger"),
    ("verger-visual", r"C:\visual projects\verger", "C--visual-projects-verger"),
    ("invoice", None, "C--visual-projects-invoice-invoice"),
]


def size(path):
    total = 0
    for root, _, files in os.walk(path):
        for f in files:
            try:
                total += os.path.getsize(os.path.join(root, f))
            except OSError:
                pass
    return total / 1024 / 1024


def copy(src, dst):
    if os.path.isdir(src):
        shutil.copytree(src, dst, dirs_exist_ok=False, ignore=shutil.ignore_patterns("__pycache__"))
    elif os.path.isfile(src):
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(src, dst)


for name, src, conv in PROJECTS:
    out = os.path.join(DEST, name)
    if src:
        for rel in ("tickets", r"roles\log", "goals", "errors", "decisions.md", "rpv.json", r"dispatcher\runs"):
            copy(os.path.join(src, ".claude", rel), os.path.join(out, ".claude", rel))
        for pat in ("*.log", "*.md", "*.json"):
            for f in glob.glob(os.path.join(src, ".claude", "dispatcher", pat)):
                copy(f, os.path.join(out, ".claude", "dispatcher", os.path.basename(f)))
    copy(os.path.join(CONV, conv), os.path.join(out, "claude-conversations"))
    print(f"{name}: {size(out):.0f} МБ" if os.path.isdir(out) else f"{name}: нет данных")
print(f"всего: {size(DEST):.0f} МБ")

